"""
OpenAI-compatible embedding provider for Sonorus Cognis memory.

The module and class keep their original Cognis names for import compatibility,
but Gemini embeddings are intentionally unsupported. Long-term memory is only
enabled for Sonorus's OpenAI-compatible providers: OpenAI and OpenRouter.
"""

import logging
import math
import os
from typing import List

from cognis.embeddings.base import BaseEmbedder, EmbeddingResult
from cognis.utils import LRUCache

logger = logging.getLogger(__name__)


def _truncate_pad_and_normalize(vec: List[float], dim: int) -> List[float]:
    values = [float(x) for x in vec[:dim]]
    if len(values) < dim:
        values.extend([0.0] * (dim - len(values)))
    norm = math.sqrt(sum(x * x for x in values))
    if norm > 0:
        return [x / norm for x in values]
    return values


class OpenAICompatibleEmbedder(BaseEmbedder):
    """Embedding client backed by OpenAI-compatible APIs."""

    def __init__(
        self,
        api_key: str = None,
        model: str = "text-embedding-3-small",
        full_dim: int = 768,
        small_dim: int = 256,
    ):
        self._api_key = api_key
        self._model = model
        self._full_dim = full_dim
        self._small_dim = small_dim
        self._cache = LRUCache(max_size=500, ttl_seconds=3600)

    def _load_provider_settings(self):
        try:
            from utils.settings import load_settings
            settings = load_settings()
            return settings.get("llm", {}) or {}, settings.get("memory", {}) or {}
        except Exception:
            return {}, {}

    def _get_key(self, llm_settings: dict, provider: str) -> str:
        if self._api_key:
            return self._api_key
        provider_key = (llm_settings.get(provider, {}) or {}).get("api_key", "")
        if provider_key:
            return provider_key
        env_names = {
            "openai": ("OPENAI_API_KEY",),
            "openrouter": ("OPENROUTER_API_KEY",),
        }
        for name in env_names.get(provider, ()):
            value = os.environ.get(name)
            if value:
                return value
        return ""

    def _embedding_request(self, text: str) -> List[float]:
        from openai import OpenAI

        llm_settings, memory_settings = self._load_provider_settings()
        provider = llm_settings.get("provider", "gemini")

        if provider not in ("openai", "openrouter"):
            raise ValueError(
                f"Long-term memory embeddings require OpenAI or OpenRouter provider, got {provider!r}"
            )

        api_key = self._get_key(llm_settings, provider)
        if not api_key:
            raise ValueError(f"No {provider} API key configured for memory embeddings")

        configured_model = memory_settings.get("embedding_model") or self._model
        if provider == "openrouter":
            base_url = "https://openrouter.ai/api/v1"
            model = configured_model or "openai/text-embedding-3-small"
            if "/" not in model:
                model = f"openai/{model}"
        else:
            openai_settings = llm_settings.get("openai", {}) or {}
            base_url = openai_settings.get("api_url", "").strip() or None
            model = configured_model or "text-embedding-3-small"
            if model.startswith("openai/"):
                model = model.split("/", 1)[1]

        client = OpenAI(api_key=api_key, base_url=base_url)
        try:
            response = client.embeddings.create(
                input=[text],
                model=model,
                dimensions=self._full_dim,
            )
        except Exception:
            response = client.embeddings.create(input=[text], model=model)

        return list(response.data[0].embedding)

    def _embed(self, text: str) -> EmbeddingResult:
        cache_key = f"emb:{self._full_dim}:{self._small_dim}:{text[:500]}"
        cached = self._cache.get(cache_key)
        if cached is not None:
            return cached

        full_vec = _truncate_pad_and_normalize(self._embedding_request(text), self._full_dim)
        small_vec = _truncate_pad_and_normalize(full_vec, self._small_dim)
        result = EmbeddingResult(embeddings={
            self._full_dim: full_vec,
            self._small_dim: small_vec,
        })
        self._cache.set(cache_key, result)
        return result

    def embed_query(self, text: str) -> EmbeddingResult:
        return self._embed(text)

    def embed_document(self, text: str) -> EmbeddingResult:
        return self._embed(text)

    def embed_documents_batch(self, texts: List[str]) -> List[EmbeddingResult]:
        return [self.embed_document(t) for t in texts]


# Backward-compatible name used by cognis.memory.
GeminiEmbedder = OpenAICompatibleEmbedder
